function solve(equations, values, queries) {
  const rows = Math.min(equations.length, values.length);
  const isKnown = (name) => {
    for (const row of equations) {
      for (const entry of row) {
        if (entry === name) return true;
      }
    }
    return false;
  };
  const answer = (src, dst) => {
    if (!isKnown(src) || !isKnown(dst)) return -1;
    if (src === dst) return 1;
    const visited = new Set([src]);
    const walk = (node) => {
      if (node === dst) return 1;
      for (let i = 0; i < rows; i++) {
        const row = equations[i];
        if (row.length < 2) continue;
        const a = row[0];
        const b = row[1];
        if (a === b) continue;
        let next = null;
        let factor = 0;
        if (a === node && !visited.has(b)) {
          next = b;
          factor = values[i];
        } else if (b === node && !visited.has(a) && values[i] !== 0) {
          next = a;
          factor = 1 / values[i];
        }
        if (next === null) continue;
        visited.add(next);
        const rest = walk(next);
        if (rest !== null) return factor * rest;
      }
      return null;
    };
    const found = walk(src);
    return found === null ? -1 : found;
  };
  const out = [];
  for (const q of queries) {
    if (!Array.isArray(q) || q.length < 2) {
      out.push(-1);
      continue;
    }
    out.push(answer(q[0], q[1]));
  }
  return out;
}

function solve(equations, values, queries) {
  const rows = Math.min(equations.length, values.length);
  const known = new Set();
  const adj = new Map();
  for (const row of equations) {
    for (const entry of row) known.add(entry);
  }
  for (let i = 0; i < rows; i++) {
    const row = equations[i];
    if (row.length < 2) continue;
    const a = row[0];
    const b = row[1];
    if (a === b) continue;
    if (!adj.has(a)) adj.set(a, []);
    if (!adj.has(b)) adj.set(b, []);
    adj.get(a).push([b, values[i]]);
    if (values[i] !== 0) adj.get(b).push([a, 1 / values[i]]);
  }
  const out = [];
  for (const q of queries) {
    if (!Array.isArray(q) || q.length < 2) {
      out.push(-1);
      continue;
    }
    const src = q[0];
    const dst = q[1];
    if (!known.has(src) || !known.has(dst)) {
      out.push(-1);
      continue;
    }
    if (src === dst) {
      out.push(1);
      continue;
    }
    const visited = new Set([src]);
    const walk = (node) => {
      if (node === dst) return 1;
      const neighbours = adj.get(node) || [];
      for (const edge of neighbours) {
        if (visited.has(edge[0])) continue;
        visited.add(edge[0]);
        const rest = walk(edge[0]);
        if (rest !== null) return edge[1] * rest;
      }
      return null;
    };
    const found = walk(src);
    out.push(found === null ? -1 : found);
  }
  return out;
}
